import {t} from '../utilities/i18n'
import React, {useEffect, useState} from 'react'
import {useNavigate} from 'react-router-dom'
import {toast} from 'react-toastify'
import Constants from '../Constants'
import {main, navigationState} from '../utilities/appState'
import {fetchRostersByUser, deleteRoster} from '../utilities/api'
import {hydrateRoster} from '../utilities/rosterModel'
import {encodeRosterCode, copyText} from '../utilities/rosterCode'
import {notifyHydrateReport} from './hydrateNotice'
import {isSupporter, getSupportUntil, formatSupportDate, openSupportPage} from '../utilities/support'
import Modal from '../components/Modal'
import Button from '../components/Button'
import InfoNote from '../components/InfoNote'

import map from 'lodash/map'
import find from 'lodash/find'
import filter from 'lodash/filter'
import includes from 'lodash/includes'

import Styles from './styles/UserLists.module.css'

const dataBase = require('../utilities/db')

// Сохранённые списки пользователя (rosters_db): создать новый, вставить, плашки со списками
const UserLists = () => {
    const navigate = useNavigate()
    const [lists, setLists] = useState(main.rosters)
    const [toDelete, setToDelete] = useState(null)

    useEffect(() => {
        let isActive = true
        fetchRostersByUser().then(data => {
            if (!isActive || !data) return
            main.rosters = data.rosters || []
            setLists(main.rosters)
        })
        return () => { isActive = false }
    }, [])

    const handleNew = () => navigate('/chooseGrandFaction')

    const handlePaste = () => navigate('/pasteList')

    const handleOpen = (list) => () => {
        hydrateRoster(list)
        notifyHydrateReport()
        navigationState.isBuilder = true
        navigate('/builder', {state: {faction: {id: list.faction_id, name: list.faction}}})
    }

    const handleShare = async (list) => {
        const copied = await copyText(encodeRosterCode(list.id))
        toast[copied ? 'success' : 'error'](copied ? t('Code copied') : `${t('Could not copy the code')}: ${encodeRosterCode(list.id)}`, Constants.toastParams)
    }

    const handleDelete = async () => {
        const list = toDelete
        setToDelete(null)
        const response = await deleteRoster(list.id, main.user?.id)
        if (!response) {
            toast.error(t('Could not delete the list'), Constants.toastParams)
            return
        }
        main.rosters = filter(main.rosters, item => item.id !== list.id)
        setLists(main.rosters)
        toast.success(t('List deleted'), Constants.toastParams)
    }

    const renderList = (list) => {
        const army = find(dataBase.data.faction_keyword, ['id', list.faction_id])
        return <div className={Styles.listContainer} key={list.id}>
            <button type='button' className={`${Styles.closeIcon} ${Styles.shareIcon}`} onClick={() => handleShare(list)} aria-label={t('Share code')}>
                <svg width='14' height='14' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2.5' strokeLinecap='round' strokeLinejoin='round' aria-hidden='true'><path d='M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1' /><path d='M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1' /></svg>
            </button>
            <button type='button' className={Styles.closeIcon} onClick={() => setToDelete(list)} aria-label={t('Delete list')}>
                <svg width='14' height='14' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='3' strokeLinecap='round' aria-hidden='true'><path d='M6 6l12 12M18 6L6 18' /></svg>
            </button>
            <button type='button' className={Styles.button} onClick={handleOpen(list)}>
                {army?.moreInfoImage ? <img src={army.moreInfoImage} alt={army?.name} className={Styles.image} /> : <span className={Styles.image} />}
                <span className={Styles.textContainer}>
                    <span className={Styles.text}>{list.name}</span>
                    <span className={Styles.armyText}>{army?.name || list.faction}</span>
                </span>
            </button>
        </div>
    }

    const renderLimitNote = () => {
        if (includes(Constants.developersIds, main.tgId)) return null
        if (isSupporter(main.user)) {
            return <InfoNote title={t('Thank you for your support!')}>{t('No limit on saved lists until {{date}}.', {date: formatSupportDate(getSupportUntil(main.user))})}</InfoNote>
        }
        return <InfoNote title={t('You can save up to {{count}} army lists', {count: Constants.listsMax})}>
            <p className={Styles.limitText}>{t('Support the app with any donation from 1 EUR and the limit is removed for a month.')}</p>
            <Button className={Styles.limitButton} onClick={openSupportPage}>{t('Support the app')}</Button>
        </InfoNote>
    }

    return <div id='column' className='Chapter'>
        <Button className={Styles.newRosterButton} onClick={handleNew}>{t('New List')}</Button>
        <Button className={Styles.newRosterButton} type='secondary' onClick={handlePaste}>{t('Paste List')}</Button>
        {renderLimitNote()}
        <div className={Styles.buttonContainer}>{map(lists, renderList)}</div>
        <Modal visible={Boolean(toDelete)} title={t('Delete roster?')} onClose={() => setToDelete(null)}>
            <p className={Styles.modalText}>{toDelete?.name}</p>
            <Button type='danger' className={Styles.newRosterButton} onClick={handleDelete}>{t('Delete')}</Button>
            <Button type='secondary' className={Styles.newRosterButton} onClick={() => setToDelete(null)}>{t('Cancel')}</Button>
        </Modal>
    </div>
}

export default UserLists
